```c
int
_gnutls_x509_dn_to_string(const char *oid, void *value,
                          int value_size, gnutls_datum_t * str)
{
    ...
    if (oentry->asn_desc != NULL) { /* complex */
        ret = decode_complex_string(oentry, value, value_size, &tmp);
        if (ret < 0) {
            goto unknown_oid;
        }
    } else {
        ret = _gnutls_x509_decode_string(oentry->etype, value,
                                         value_size, &tmp, 0);
        if (ret < 0) {
            goto unknown_oid;
        }
    }

    ret = str_escape(&tmp, str);
    _gnutls_free_datum(&tmp);
    ...
}
```

If `decode_complex_string` fails, it goes to `unknown_oid` which calls `data2hex`. But `tmp` was never initialized in that path. However, `data2hex` allocates `str->data` and sets `str->size`, so that should be fine.

